const moduleWrapperStack = [];
let current = undefined;
export const moduleWrapper = {
  get current() {
    if (moduleWrapperStack.length === 0 && !current) {
      throw new Error("No chayns api instance initialized");
    }
    return moduleWrapperStack.length > 0 ? moduleWrapperStack[moduleWrapperStack.length - 1] : current;
  },
  set current(chayns) {
    current = chayns;
  }
};
export const chaynsApis = {};
export const getChaynsApi = id => {
  return chaynsApis[id];
};
export const addModuleWrapper = (id, chayns) => {
  moduleWrapperStack.push(chayns);
  chaynsApis[id] = chayns.functions;
};
export const removeModuleWrapper = (id, chayns) => {
  const index = moduleWrapperStack.indexOf(chayns);
  if (index > -1) {
    moduleWrapperStack.splice(index, 1);
  }
  delete moduleWrapperStack[id];
};